class Task:
    """Represents a single task in our management system."""

    def __init__(self, name, priority=3, estimated_hours=1.0):
        self.name = name
        self.priority = priority
        self.estimated_hours = estimated_hours
        self.complete = False
        self.tags = []

    def mark_complete(self):
        self.complete = True

    def add_tag(self, tag):
        if tag not in self.tags:
            self.tags.append(tag)

    def __str__(self):
        status = "✓" if self.complete else "○"
        return f"[{status}] {self.name} (Priority: {self.priority})"
